# 修复KeyError问题并完成分析
import numpy as np

# 检查数据完整性
print(f"history_features长度: {len(history_features)}")
print(f"forecast_features长度: {len(forecast_features)}")
print(f"historical_samples长度: {len(historical_samples)}")

# 确保有足够的数据
if len(history_features) > 0 and len(forecast_features) > 0 and len(historical_samples) > 0:
    # 获取当前事件特征（最后时刻）
    current_features = history_features[-1]

    # 获取最终预测特征（最后提前期）
    final_forecast = forecast_features[-1]

    # 计算一致性指标
    def calculate_consistency_safe(current_feat, forecast_feat, historical_feats):
        """安全计算一致性指标"""
        metrics = {}

        try:
            # 强度变化一致性
            hist_intensity_changes = []
            for hist_feat in historical_feats:
                if 'max_intensity' in hist_feat and 'max_intensity' in current_feat:
                    change = hist_feat['max_intensity'] - current_feat['max_intensity']
                    hist_intensity_changes.append(change)

            if hist_intensity_changes and 'max_intensity' in forecast_feat:
                forecast_intensity_change = forecast_feat['max_intensity'] - current_feat['max_intensity']

                hist_changes_array = np.array(hist_intensity_changes)
                metrics['intensity_in_range'] = bool(
                    forecast_intensity_change >= hist_changes_array.min() and 
                    forecast_intensity_change <= hist_changes_array.max()
                )
                metrics['intensity_percentile'] = float(
                    np.sum(hist_changes_array <= forecast_intensity_change) / len(hist_changes_array)
                )
            else:
                metrics['intensity_in_range'] = None
                metrics['intensity_percentile'] = None

            # 范围变化一致性
            hist_coverage_changes = []
            for hist_feat in historical_feats:
                if 'coverage_pixels' in hist_feat and 'coverage_pixels' in current_feat:
                    change = hist_feat['coverage_pixels'] - current_feat['coverage_pixels']
                    hist_coverage_changes.append(change)

            if hist_coverage_changes and 'coverage_pixels' in forecast_feat:
                forecast_coverage_change = forecast_feat['coverage_pixels'] - current_feat['coverage_pixels']

                hist_cov_changes_array = np.array(hist_coverage_changes)
                metrics['coverage_in_range'] = bool(
                    forecast_coverage_change >= hist_cov_changes_array.min() and 
                    forecast_coverage_change <= hist_cov_changes_array.max()
                )
                metrics['coverage_percentile'] = float(
                    np.sum(hist_cov_changes_array <= forecast_coverage_change) / len(hist_cov_changes_array)
                )
            else:
                metrics['coverage_in_range'] = None
                metrics['coverage_percentile'] = None

        except Exception as e:
            print(f"计算一致性时出错: {e}")
            metrics['error'] = str(e)

        return metrics

    # 计算移动一致性
    def calculate_movement_consistency_safe(current_centroid, forecast_centroids, historical_centroids):
        """安全计算移动一致性"""
        try:
            if len(forecast_centroids) < 2 or len(historical_centroids) == 0:
                return {"movement_consistency": "insufficient_data"}

            # 获取当前质心
            if np.isnan(current_centroid[0]) or np.isnan(current_centroid[1]):
                return {"movement_consistency": "invalid_current_centroid"}

            # 计算预测的移动向量
            forecast_vector = forecast_centroids[-1] - forecast_centroids[0]
            forecast_distance = np.linalg.norm(forecast_vector)

            if forecast_distance == 0:
                return {"movement_consistency": "no_forecast_movement"}

            # 计算历史样本与当前事件的相对位置
            historical_vectors = []
            for centroid in historical_centroids:
                if not np.isnan(centroid[0]) and not np.isnan(centroid[1]):
                    vector = centroid - np.array(current_centroid)
                    hist_distance = np.linalg.norm(vector)
                    if hist_distance > 0:
                        historical_vectors.append(vector)

            if historical_vectors:
                # 计算预测方向与历史方向的相似度
                similarities = []
                for hist_vector in historical_vectors:
                    hist_distance = np.linalg.norm(hist_vector)
                    if hist_distance > 0:
                        # 计算余弦相似度
                        cos_sim = np.dot(forecast_vector, hist_vector) / (forecast_distance * hist_distance)
                        similarities.append(cos_sim)

                if similarities:
                    avg_similarity = np.mean(similarities)
                    return {
                        "movement_similarity": float(avg_similarity),
                        "movement_consistent": avg_similarity > 0.3  # 相似度>0.3认为方向一致
                    }

            return {"movement_consistency": "cannot_compute"}

        except Exception as e:
            return {"movement_consistency": f"error: {str(e)}"}

    # 准备质心数据
    forecast_centroid_array = []
    for f in forecast_features:
        if 'centroid_col' in f and 'centroid_row' in f:
            if not np.isnan(f['centroid_col']) and not np.isnan(f['centroid_row']):
                forecast_centroid_array.append([f['centroid_col'], f['centroid_row']])

    historical_centroid_array = []
    for f in historical_samples:
        if 'centroid_col' in f and 'centroid_row' in f:
            if not np.isnan(f['centroid_col']) and not np.isnan(f['centroid_row']):
                historical_centroid_array.append([f['centroid_col'], f['centroid_row']])

    # 获取当前质心
    current_centroid = (current_features.get('centroid_col', np.nan), 
                       current_features.get('centroid_row', np.nan))

    # 计算一致性指标
    consistency_metrics = calculate_consistency_safe(current_features, final_forecast, historical_samples)

    if forecast_centroid_array and historical_centroid_array:
        forecast_centroid_array = np.array(forecast_centroid_array)
        historical_centroid_array = np.array(historical_centroid_array)
        movement_consistency = calculate_movement_consistency_safe(
            current_centroid, forecast_centroid_array, historical_centroid_array
        )
    else:
        movement_consistency = {"movement_consistency": "insufficient_data"}

    # 计算形态变化（强度-范围关系）
    def calculate_morphology_change(current_feat, forecast_feat, historical_feats):
        """计算形态变化"""
        try:
            # 当前事件的强度-范围比
            current_ratio = current_feat.get('max_intensity', 0) / max(current_feat.get('coverage_pixels', 1), 1)

            # 预测的强度-范围比
            forecast_ratio = forecast_feat.get('max_intensity', 0) / max(forecast_feat.get('coverage_pixels', 1), 1)

            # 历史样本的强度-范围比
            hist_ratios = []
            for hist_feat in historical_feats:
                if 'max_intensity' in hist_feat and 'coverage_pixels' in hist_feat:
                    ratio = hist_feat['max_intensity'] / max(hist_feat['coverage_pixels'], 1)
                    hist_ratios.append(ratio)

            if hist_ratios:
                hist_ratios_array = np.array(hist_ratios)
                forecast_ratio_change = forecast_ratio - current_ratio

                return {
                    "current_morphology_ratio": float(current_ratio),
                    "forecast_morphology_ratio": float(forecast_ratio),
                    "morphology_change": float(forecast_ratio_change),
                    "morphology_in_historical_range": bool(
                        forecast_ratio_change >= hist_ratios_array.min() and 
                        forecast_ratio_change <= hist_ratios_array.max()
                    )
                }
            else:
                return {"morphology_analysis": "insufficient_data"}

        except Exception as e:
            return {"morphology_analysis": f"error: {str(e)}"}

    morphology_analysis = calculate_morphology_change(current_features, final_forecast, historical_samples)

    # 准备最终结果
    result = {
        "analysis_summary": {
            "historical_sample_count": len(historical_samples),
            "forecast_horizon_minutes": list(map(int, forecast.lead_minutes)),
            "comparison_valid": True
        },
        "current_event_characteristics": {
            "intensity": float(current_features.get('max_intensity', 0)),
            "coverage": int(current_features.get('coverage_pixels', 0)),
            "mean_intensity": float(current_features.get('mean_intensity', 0))
        },
        "forecast_characteristics": {
            "final_intensity": float(final_forecast.get('max_intensity', 0)),
            "final_coverage": int(final_forecast.get('coverage_pixels', -1)),
            "final_mean_intensity": float(final_forecast.get('mean_intensity', 0))
        },
        "consistency_assessment": {
            "intensity": {
                "change": float(final_forecast.get('max_intensity', 0) - current_features.get('max_intensity', 0)),
                "percentile": consistency_metrics.get('intensity_percentile'),
                "in_historical_range": consistency_metrics.get('intensity_in_range'),
                "interpretation": "强度变化在历史样本中的相对位置"
            },
            "coverage": {
                "change": int(final_forecast.get('coverage_pixels', 0) - current_features.get('coverage_pixels', 0)),
                "percentile": consistency_metrics.get('coverage_percentile'),
                "in_historical_range": consistency_metrics.get('coverage_in_range'),
                "interpretation": "范围变化在历史样本中的相对位置"
            },
            "movement": movement_consistency,
            "morphology": morphology_analysis
        },
        "artifact_urls": {
            "intensity_comparison": "/api/artifacts/dda42b846b534aa2bcbc4d7ce1b2be9c.png",
            "movement_morphology": "/api/artifacts/64748d347c9b4a83ba727871d1f00192.png"
        }
    }

    print("分析完成，生成最终结果:")
    print(result)

else:
    result = {
        "error": "数据不足，无法完成分析",
        "available_data": {
            "history_features": len(history_features),
            "forecast_features": len(forecast_features),
            "historical_samples": len(historical_samples)
        }
    }
    print(result)
